<script>
(function() {
  // Initialize active bag swatches per card
  document.querySelectorAll('.eid-card').forEach(card => {
    const activeBags = card.querySelector('[data-target="bags"] .eid-swatch.active');
    if (activeBags) card.dataset.bagsId = activeBags.dataset.id;
  });

  // Swatch click handler (keeps active state logic even though there's currently one option)
  document.querySelectorAll('.eid-swatch').forEach(swatch => {
    swatch.addEventListener('click', function() {
      const group = this.parentElement;
      const target = group.dataset.target;
      const card = this.closest('.eid-card');
      group.querySelectorAll('.eid-swatch').forEach(s => s.classList.remove('active'));
      this.classList.add('active');
      if (target === 'bags') card.dataset.bagsId = this.dataset.id;
    });
  });

  // Add to Cart — TEMP: bags NOT added to cart; sent as line item property instead.
  // When fulfillment bug is fixed, revert this handler to add bags as a real line item.
  document.querySelectorAll('.eid-cta').forEach(btn => {
    btn.addEventListener('click', async function() {
      const card = this.closest('.eid-card');

      // Read selected bag color for the warehouse-readable property
      const bagSwatch = card.querySelector('[data-target="bags"] .eid-swatch.active');
      const bagLabel = bagSwatch ? (bagSwatch.getAttribute('aria-label') || 'Pink') : 'Pink';
      const bagQty = parseInt(card.dataset.bagsQty || '1');
      const bagCountText = (bagQty * 50) + ' Milk Bags';

      // Pump line item carries a property describing the free bag gift.
      // Visible to customer on cart, order confirmation, and packing slip.
      const items = [{
        id: parseInt(card.dataset.pumpId),
        quantity: 1,
        properties: {
          'هدية العيد 🌙 · Free Eid Gift': bagCountText + ' — ' + bagLabel
        }
      }];

      const original = this.innerText;
      this.disabled = true;
      this.innerText = '...';
      try {
        const res = await fetch('/cart/add.js', {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({ items: items })
        });
        if (res.ok) window.location.href = '/cart';
        else { this.innerText = original; this.disabled = false; }
      } catch(e) { this.innerText = original; this.disabled = false; }
    });
  });
})();
</script>

