    <!-- 🔴 RED ALERT DOT -->
    <span style="
      position: relative;
      width: {{ dot_size | default: '8px' }};
      height: {{ dot_size | default: '8px' }};
      display: inline-block;
    ">
      <!-- ping -->
      <span style="
        position: absolute;
        inset: 0;
        background: {{ dot_color | default: '#dc2525' }};
        border-radius: 50%;
        animation: lc-ping 1s cubic-bezier(0,0,0.2,1) infinite;
      "></span>

