<form method="post" action="/cart/add" class="buy-now-form" style="margin-top: 10px;">
  <input type="hidden" name="id" value="{{ product.selected_or_first_available_variant.id }}">
  <input type="hidden" name="quantity" value="1">

  <button type="submit" name="checkout" class="buy-now-btn">
    <span class="btn-text">
      {%- if is_arabic -%}
        اطلب الآن
      {%- else -%}
        Buy Now
      {%- endif -%}
    </span>
    <span class="btn-loader" style="display:none;">...</span>
  </button>
</form>

<style>
  .buy-now-btn {
    width: 100%;
    background-color: #FF8C42; /* Your Orange Color */
    color: #FFFFFF;
    border: none;
    padding: 12px;
    font-size: 16px;
    font-weight: bold;
    cursor: pointer;
    border-radius: 4px; /* Matches Shopify rounded corners */
    transition: background 0.3s;
    font-family: Helvetica, Arial, sans-serif;
  }

  .buy-now-btn:hover {
    background-color: #e07b3a; /* Slightly darker orange on hover */
  }

  /* RTL Support */
  {%- if is_arabic -%}
  .buy-now-btn {
    font-family: 'Helvetica', 'Arial', sans-serif; /* Or your Arabic font */
  }
  {%- endif -%}
</style>

<script>
  document.querySelector('.buy-now-form').addEventListener('submit', function(e) {
    e.preventDefault();

    // 1. Change Text to "Processing..." so user knows it worked
    const btn = this.querySelector('.buy-now-btn');
    const textSpan = this.querySelector('.btn-text');
    const loaderSpan = this.querySelector('.btn-loader');

    const isAr = "{{ is_arabic }}" === "true";
    textSpan.textContent = isAr ? "جاري التحويل..." : "Processing...";

    // 2. Send to Cart
    const formData = new FormData(this);
    fetch('/cart/add.js', {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(data => {
      // 3. Go straight to Checkout (Skip Cart Page)
      window.location.href = '/checkout';
    })
    .catch(error => {
      console.error('Error:', error);
      // If error, revert button text
      textSpan.textContent = isAr ? "اطلب الآن" : "Buy Now";
    });
  });
</script>

