<script>
  // Simple Date Logic (No Lag)
  const MIN_DAYS = 2; // Fast delivery
  const MAX_DAYS = 4; // Buffer

  function addDays(date, days) {
    const d = new Date(date);
    d.setDate(d.getDate() + days);
    return d;
  }

  function formatDate(date, locale) {
    // Smart formatting: "Feb 10" for English, "10 فبراير" for Arabic
    const options = { month: "short", day: "numeric" };
    return date.toLocaleDateString(locale, options);
  }

  document.addEventListener("DOMContentLoaded", () => {
    const today = new Date();
    // Detect language from HTML lang tag or URL, default to 'en'
    const isArabic = document.documentElement.lang === 'ar' || window.location.pathname.includes('/ar');
    const locale = isArabic ? 'ar-SA' : 'en-US';

    const start = addDays(today, MIN_DAYS);
    const end = addDays(today, MAX_DAYS);

    const startEl = document.getElementById("delivery-start");
    const endEl = document.getElementById("delivery-end");

    if(startEl) startEl.textContent = formatDate(start, locale);
    if(endEl) endEl.textContent = formatDate(end, locale);
  });
</script>

